INSERT INTO `measures` (`id`, `external_measure_no`, `response_objective`, `policy_section`, `government_measure`, `default_lead_agency`, `default_supporting_agencies`, `suggested_key_indicator`, `baseline_text`, `default_status`, `default_means_of_verification`, `default_update_owner`, `is_active`, `sort_order`, `created_at`, `updated_at`) VALUES
	(1, 1, '1. Energy Supply and Price Mitigation', 'Securing Adequate Oil Supply and Mitigating Price Escalation', 'Securing oil supply', 'DOE', 'DFA; PNOC', 'Average fuel supply in days by type; barrels or tonnes secured/procured', 'As of March 20, 2026, average nationwide fuel supply stood at 45.10 days.\nBy fuel type: gasoline 53.14; diesel 45.82; kerosene 97.93; jet fuel 38.62; fuel oil 61.49; LPG 23.51.', 'Amber', 'DOE / DFA / PNOC updates reflected in the official government measures matrix.', 'DOE', 1, 1, '2026-04-24 14:50:22', '2026-04-24 14:50:22'),
	(2, 2, '1. Energy Supply and Price Mitigation', 'Securing Adequate Oil Supply and Mitigating Price Escalation', 'Securing electricity supply', 'DOE', 'DOF', 'Power projects online; MW added; market or pricing measures issued', 'Indonesia assured steady coal supply.\nDOE coordinated with generators and NGCP.\n23 power projects, with over 900 MW, are expected online by April or May 2026.', 'Amber', 'DOE / DOF / ERC updates reflected in the official government measures matrix.', 'DOE', 1, 2, '2026-04-24 14:50:22', '2026-04-24 14:50:22'),
	(3, 3, '1. Energy Supply and Price Mitigation', 'Securing Adequate Oil Supply and Mitigating Price Escalation', 'Staggered implementation of fuel price increases and provision of fuel discounts', 'DOE', '', 'Number of staggered implementations; number of discount programs operational', 'Staggered fuel price increases were implemented on March 10 to 16 and March 17 to 23, 2026.\nDOE is coordinating continuation of fuel discount programs.', 'Amber', 'DOE implementation updates reflected in the official government measures matrix.', 'DOE', 1, 3, '2026-04-24 14:50:22', '2026-04-24 14:50:22'),
	(4, 4, '1. Energy Supply and Price Mitigation', 'Securing Adequate Oil Supply and Mitigating Price Escalation', 'Monitoring against hoarding and profiteering of petroleum products', 'DOE', 'DILG; PNP', 'Number of outlets monitored, investigated, or acted upon', 'DOE coordinated with PNP, LGUs, and electric cooperatives on fuel retail monitoring.\n403 gas stations had temporarily ceased operations as of March 20, 2026.', 'Amber', 'DOE / PNP monitoring updates reflected in the official government measures matrix.', 'DOE', 1, 4, '2026-04-24 14:50:23', '2026-04-24 14:50:23'),
	(5, 5, '1. Energy Supply and Price Mitigation', 'Securing Adequate Oil Supply and Mitigating Price Escalation', 'Implementation of energy saving measures', 'DOE', 'All government agencies and instrumentalities', 'Number of agencies implementing measures; compliance score; spot checks', 'Four-day work week and other flexible work arrangements started on March 9, 2026.\nAt least 1,130 government entities were implementing flexible work arrangements.\nDOE spot-check score: 86.47%.', 'Green', 'DOE compliance monitoring reflected in the official government measures matrix.', 'DOE', 1, 5, '2026-04-24 14:50:23', '2026-04-24 14:50:23'),
	(6, 6, '1. Energy Supply and Price Mitigation', 'Securing Adequate Oil Supply and Mitigating Price Escalation', 'Suspension of excise tax', 'DOF', 'DOE; PLLO', 'Weekly Dubai crude average versus trigger; preparatory actions completed', 'RA No. 12316 was signed on March 25, 2026.\nThe law authorizes excise tax suspension or reduction if Dubai crude reaches at least USD 80 per barrel for one month.', 'Amber', 'DOF / DOE / PLLO policy update reflected in the official government measures matrix.', 'DOF', 1, 6, '2026-04-24 14:50:23', '2026-04-24 14:50:23'),
	(7, 7, '2. Transport Continuity and Affordability', 'Keeping Transportation Moving and Affordable', 'Provision of fuel subsidy and cash assistance to PUV drivers, TNVS, food riders, and other transport workers', 'DOTr', 'LTFRB; DILG; DSWD', 'Number of beneficiaries paid; amount disbursed; rollout coverage', 'Fuel subsidy rollout began on March 24, 2026.\nPHP 2.5 billion was programmed for 245,066 drivers and operators of 1,180,783 units.\nAICS cash assistance reached 144,200 transport workers in Metro Manila, totaling PHP 721 million.', 'Amber', 'DOTr / LTFRB / DSWD transport assistance updates reflected in the official government measures matrix.', 'DOTr', 1, 7, '2026-04-24 14:50:23', '2026-04-24 14:50:23'),
	(8, 8, '2. Transport Continuity and Affordability', 'Keeping Transportation Moving and Affordable', 'Provision of free rides (Libreng Sakay)', 'DOTr', 'LTFRB and partner agencies', 'Number of routes operational; units deployed; commuter coverage', 'Love Bus Libreng Sakay continued in Metro Cebu, Metro Davao, and Metro Manila.\nOn March 26, 2026, SOS Libreng Sakay covered 10 route groupings.\nAvailable partner units totaled 33.', 'Amber', 'DOTr / LTFRB route deployment updates reflected in the official government measures matrix.', 'DOTr', 1, 8, '2026-04-24 14:50:23', '2026-04-24 14:50:23'),
	(9, 9, '2. Transport Continuity and Affordability', 'Keeping Transportation Moving and Affordable', 'Discounts on trains', 'DOTr', 'LRT/MRT operators', 'Number of rail lines covered; passengers reached', 'All passengers on LRT-2 and MRT-3 have been receiving a 50% fare discount since March 23, 2026.\nDOTr is coordinating to extend the same discount to LRT-1.', 'Amber', 'DOTr rail fare discount updates reflected in the official government measures matrix.', 'DOTr', 1, 9, '2026-04-24 14:50:23', '2026-04-24 14:50:23'),
	(10, 10, '2. Transport Continuity and Affordability', 'Keeping Transportation Moving and Affordable', 'Implementation of temporary toll discount', 'DOTr', 'Toll operators', 'Number of tollways implementing approved discounts; rebates processed', 'A two-month toll discount program took effect on March 23, 2026 for Class 1 PUVs, Class 2 PUBs, and Class 3 freight food transport services.\nRebates are credited weekly.', 'Green', 'DOTr toll discount implementation updates reflected in the official government measures matrix.', 'DOTr', 1, 10, '2026-04-24 14:50:23', '2026-04-24 14:50:23'),
	(11, 11, '2. Transport Continuity and Affordability', 'Keeping Transportation Moving and Affordable', 'Sea transport measures', 'PPA', 'MARINA', 'Number of sea transport fare or fee measures effective; routes covered', 'MARINA allowed up to a 20% passenger fare increase and fee relief on March 10, 2026.\nRORO terminal fees for vehicles carrying agricultural products were approved for reduction to PHP 1 effective on or before April 15, 2026.', 'Amber', 'PPA / MARINA / DOTr sea transport updates reflected in the official government measures matrix.', 'PPA', 1, 11, '2026-04-24 14:50:23', '2026-04-24 14:50:23'),
	(12, 12, '2. Transport Continuity and Affordability', 'Keeping Transportation Moving and Affordable', 'Air transport measures', 'CAAP', 'CAB', 'Number of aviation fee measures effective; fuel surcharge level', 'CAAP announced fee reductions effective April 1, 2026.\nCAB shifted to a 15-day passenger fuel surcharge cycle and moved to Level 8 for April 1 to 15, 2026.', 'Amber', 'CAAP / CAB air transport updates reflected in the official government measures matrix.', 'CAAP', 1, 12, '2026-04-24 14:50:23', '2026-04-24 14:50:23'),
	(13, 13, '3. Food Supply and Affordability', 'Ensuring Stable Food Supply and Affordability', 'Provision of fuel and fertilizer subsidies to farmers and fisherfolk', 'DA', 'BFAR', 'Number of farmers or fisherfolk assisted; quantity or value of support', '26,230 farmers are set to receive PHP 3,000 fuel subsidy from remaining FY 2023 and FY 2024 funds.\n10,949 fisherfolk are receiving continuing fuel assistance.\nFertilizer support covered 1.16 million hectares of rice area.', 'Amber', 'DA / BFAR farm input support updates reflected in the official government measures matrix.', 'DA', 1, 13, '2026-04-24 14:50:23', '2026-04-24 14:50:23'),
	(14, 14, '3. Food Supply and Affordability', 'Ensuring Stable Food Supply and Affordability', 'Ensuring adequate rice supply and distribution', 'DA', 'DBM', 'Number of P20 centers operating; rice buffer stock; rice distribution actions', 'P20 Rice program had 627 centers nationwide, 254 with regular selling schedules.\nRice buffer stock was about 7 million 50-kg bags, or about 379,000 metric tons, equal to 10 days of national consumption.', 'Amber', 'DA / DBM rice supply updates reflected in the official government measures matrix.', 'DA', 1, 14, '2026-04-24 14:50:23', '2026-04-24 14:50:23'),
	(15, 15, '3. Food Supply and Affordability', 'Ensuring Stable Food Supply and Affordability', 'Ensuring stable prices of food products', 'DA', 'DTI', 'Price monitoring actions; compliance with SRPs; food/fertilizer stocks', 'DTI reported stable BNPC prices and about two months of manufactured BNPC inventory.\nAs of the first week of March 2026, no retailers were found selling above SRPs.\nFertilizer stocks totaled about 2.24 million bags.', 'Amber', 'DA / DTI food price monitoring reflected in the official government measures matrix.', 'DA', 1, 15, '2026-04-24 14:50:23', '2026-04-24 14:50:23'),
	(16, 16, '4. Social Protection and OFW Assistance', 'Protecting Overseas Filipinos', 'Repatriation assistance', 'DMW', 'DFA; DSWD', 'Number of OFWs/dependents assisted, repatriated, and pending', 'From March 5 to 23, 2026, 2,052 OFWs and 578 dependents arrived in Manila.\nAs of March 24, 2026, 16,660 OFWs had received assistance and 586 OFs remained awaiting repatriation.', 'Amber', 'DMW / DFA / DSWD repatriation updates reflected in the official government measures matrix.', 'DMW', 1, 16, '2026-04-24 14:50:23', '2026-04-24 14:50:23'),
	(17, 17, '4. Social Protection and OFW Assistance', 'Others', 'Easing school costs and other assistance for education', 'DepEd', 'DOLE and other concerned agencies', 'Number of schools, learners, or jobseekers covered by support measures', 'Bagong Pilipinas Serbisyo Fair activities in schools were conducted in pilot sites on March 13, 2026, in NCR on March 19, 2026, and nationwide on March 25, 2026.\nDepEd is also implementing no additional graduation fees and YAKAP in schools.', 'Amber', 'DepEd education assistance updates reflected in the official government measures matrix.', 'DepEd', 1, 17, '2026-04-24 14:50:23', '2026-04-24 14:50:23'),
	(18, 18, '4. Social Protection and OFW Assistance', 'Others', 'Assisting affected workers', 'SSS', '', 'Number of claims processed or paid; amount of benefits released', 'SSS is administering the Involuntary Separation Benefit for qualified members involuntarily separated from employment.\nBenefit amount ranges from PHP 5,000 to PHP 20,000 for up to two months.', 'Green', 'SSS worker assistance update reflected in the official government measures matrix.', 'SSS', 1, 18, '2026-04-24 14:50:23', '2026-04-24 14:50:23'),
	(19, 19, '4. Social Protection and OFW Assistance', 'Others', 'Free calls and internet services for families of OFWs in the Middle East', 'DICT', 'DMW', 'Number of DICT sites or clients served; communication assistance delivered', 'DICT regional offices, Digital Transformation Centers, and provincial offices are open to provide free calls and connectivity support for families communicating with OFWs in the Middle East.', 'Green', 'DICT / DMW support service updates reflected in the official government measures matrix.', 'DICT', 1, 19, '2026-04-24 14:50:23', '2026-04-24 14:50:23'),
	(20, 20, '5. Economic Stability, Service Continuity, and Implementation Support', 'Implementation support under EO No. 110', 'Committee oversight, consolidated reporting, funding support, local coordination, and issue escalation', 'DEPDev Secretariat', 'DOE; DOF; DBM; concerned agencies', 'On-time submission rate; number of escalated issues resolved within cycle; funding mobilized', 'EO No. 110 dated March 24, 2026 declared a state of national energy emergency, adopted UPLIFT, constituted the UPLIFT Committee, and designated DEPDev as Secretariat.', 'Amber', 'Executive Order No. 110 dated March 24, 2026.', 'DEPDev Secretariat', 1, 20, '2026-04-24 14:50:23', '2026-04-24 14:50:23');
