INSERT INTO `submission_measure_updates` (`id`, `weekly_submission_id`, `measure_id`, `pillar`, `title`, `brief_description`, `lead_agency`, `supporting_agencies`, `date_initiated`, `status`, `locations_covered_text`, `beneficiary_sector_text`, `support_provided_text`, `target_beneficiaries_text`, `actual_beneficiaries_text`, `other_accomplishments_text`, `issues_text`, `action_needed_text`, `estimated_total_amount_needed`, `appropriations`, `allotment_releases`, `obligations`, `disbursements`, `additional_budget_needed`, `target_with_additional_budget_text`, `next_action_text`, `help_for_public_text`, `beneficiary_testimonial_text`, `latest_news_link`, `update_as_of_date`, `sort_order`, `created_at`, `updated_at`) VALUES
	(1, 1, 1, '1. Energy Supply and Price Mitigation', 'Securing oil supply', NULL, 'DOE', 'DFA; PNOC', NULL, 'Amber', NULL, NULL, NULL, NULL, NULL, 'As of March 20, 2026, average nationwide fuel supply stood at 45.10 days.\nBy fuel type: gasoline 53.14; diesel 45.82; kerosene 97.93; jet fuel 38.62; fuel oil 61.49; LPG 23.51.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2026-04-24 15:07:00', '2026-04-24 15:07:00'),
	(2, 1, 2, '1. Energy Supply and Price Mitigation', 'Securing electricity supply', NULL, 'DOE', 'DOF', NULL, 'Amber', NULL, NULL, NULL, NULL, NULL, 'Indonesia assured steady coal supply.\nDOE coordinated with generators and NGCP.\n23 power projects, with over 900 MW, are expected online by April or May 2026.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 2, '2026-04-24 15:07:00', '2026-04-24 15:07:00'),
	(3, 1, 3, '1. Energy Supply and Price Mitigation', 'Staggered implementation of fuel price increases and provision of fuel discounts', NULL, 'DOE', '', NULL, 'Amber', NULL, NULL, NULL, NULL, NULL, 'Staggered fuel price increases were implemented on March 10 to 16 and March 17 to 23, 2026.\nDOE is coordinating continuation of fuel discount programs.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 3, '2026-04-24 15:07:00', '2026-04-24 15:07:00'),
	(4, 1, 4, '1. Energy Supply and Price Mitigation', 'Monitoring against hoarding and profiteering of petroleum products', NULL, 'DOE', 'DILG; PNP', NULL, 'Amber', NULL, NULL, NULL, NULL, NULL, 'DOE coordinated with PNP, LGUs, and electric cooperatives on fuel retail monitoring.\n403 gas stations had temporarily ceased operations as of March 20, 2026.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 4, '2026-04-24 15:07:00', '2026-04-24 15:07:00'),
	(5, 1, 5, '1. Energy Supply and Price Mitigation', 'Implementation of energy saving measures', NULL, 'DOE', 'All government agencies and instrumentalities', NULL, 'Green', NULL, NULL, NULL, NULL, NULL, 'Four-day work week and other flexible work arrangements started on March 9, 2026.\nAt least 1,130 government entities were implementing flexible work arrangements.\nDOE spot-check score: 86.47%.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 5, '2026-04-24 15:07:00', '2026-04-24 15:07:00'),
	(6, 1, 6, '1. Energy Supply and Price Mitigation', 'Suspension of excise tax', NULL, 'DOF', 'DOE; PLLO', NULL, 'Amber', NULL, NULL, NULL, NULL, NULL, 'RA No. 12316 was signed on March 25, 2026.\nThe law authorizes excise tax suspension or reduction if Dubai crude reaches at least USD 80 per barrel for one month.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 6, '2026-04-24 15:07:00', '2026-04-24 15:07:00'),
	(7, 1, 7, '2. Transport Continuity and Affordability', 'Provision of fuel subsidy and cash assistance to PUV drivers, TNVS, food riders, and other transport workers', NULL, 'DOTr', 'LTFRB; DILG; DSWD', NULL, 'Amber', NULL, NULL, NULL, NULL, NULL, 'Fuel subsidy rollout began on March 24, 2026.\nPHP 2.5 billion was programmed for 245,066 drivers and operators of 1,180,783 units.\nAICS cash assistance reached 144,200 transport workers in Metro Manila, totaling PHP 721 million.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 7, '2026-04-24 15:07:00', '2026-04-24 15:07:00'),
	(8, 1, 8, '2. Transport Continuity and Affordability', 'Provision of free rides (Libreng Sakay)', NULL, 'DOTr', 'LTFRB and partner agencies', NULL, 'Amber', NULL, NULL, NULL, NULL, NULL, 'Love Bus Libreng Sakay continued in Metro Cebu, Metro Davao, and Metro Manila.\nOn March 26, 2026, SOS Libreng Sakay covered 10 route groupings.\nAvailable partner units totaled 33.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 8, '2026-04-24 15:07:00', '2026-04-24 15:07:00'),
	(9, 1, 9, '2. Transport Continuity and Affordability', 'Discounts on trains', NULL, 'DOTr', 'LRT/MRT operators', NULL, 'Amber', NULL, NULL, NULL, NULL, NULL, 'All passengers on LRT-2 and MRT-3 have been receiving a 50% fare discount since March 23, 2026.\nDOTr is coordinating to extend the same discount to LRT-1.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 9, '2026-04-24 15:07:00', '2026-04-24 15:07:00'),
	(10, 1, 10, '2. Transport Continuity and Affordability', 'Implementation of temporary toll discount', NULL, 'DOTr', 'Toll operators', NULL, 'Green', NULL, NULL, NULL, NULL, NULL, 'A two-month toll discount program took effect on March 23, 2026 for Class 1 PUVs, Class 2 PUBs, and Class 3 freight food transport services.\nRebates are credited weekly.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 10, '2026-04-24 15:07:00', '2026-04-24 15:07:00'),
	(11, 1, 11, '2. Transport Continuity and Affordability', 'Sea transport measures', NULL, 'PPA', 'MARINA', NULL, 'Amber', NULL, NULL, NULL, NULL, NULL, 'MARINA allowed up to a 20% passenger fare increase and fee relief on March 10, 2026.\nRORO terminal fees for vehicles carrying agricultural products were approved for reduction to PHP 1 effective on or before April 15, 2026.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 11, '2026-04-24 15:07:00', '2026-04-24 15:07:00'),
	(12, 1, 12, '2. Transport Continuity and Affordability', 'Air transport measures', NULL, 'CAAP', 'CAB', NULL, 'Amber', NULL, NULL, NULL, NULL, NULL, 'CAAP announced fee reductions effective April 1, 2026.\nCAB shifted to a 15-day passenger fuel surcharge cycle and moved to Level 8 for April 1 to 15, 2026.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 12, '2026-04-24 15:07:00', '2026-04-24 15:07:00'),
	(13, 1, 13, '3. Food Supply and Affordability', 'Provision of fuel and fertilizer subsidies to farmers and fisherfolk', NULL, 'DA', 'BFAR', NULL, 'Amber', NULL, NULL, NULL, NULL, NULL, '26,230 farmers are set to receive PHP 3,000 fuel subsidy from remaining FY 2023 and FY 2024 funds.\n10,949 fisherfolk are receiving continuing fuel assistance.\nFertilizer support covered 1.16 million hectares of rice area.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 13, '2026-04-24 15:07:00', '2026-04-24 15:07:00'),
	(14, 1, 14, '3. Food Supply and Affordability', 'Ensuring adequate rice supply and distribution', NULL, 'DA', 'DBM', NULL, 'Amber', NULL, NULL, NULL, NULL, NULL, 'P20 Rice program had 627 centers nationwide, 254 with regular selling schedules.\nRice buffer stock was about 7 million 50-kg bags, or about 379,000 metric tons, equal to 10 days of national consumption.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 14, '2026-04-24 15:07:00', '2026-04-24 15:07:00'),
	(15, 1, 15, '3. Food Supply and Affordability', 'Ensuring stable prices of food products', NULL, 'DA', 'DTI', NULL, 'Amber', NULL, NULL, NULL, NULL, NULL, 'DTI reported stable BNPC prices and about two months of manufactured BNPC inventory.\nAs of the first week of March 2026, no retailers were found selling above SRPs.\nFertilizer stocks totaled about 2.24 million bags.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 15, '2026-04-24 15:07:00', '2026-04-24 15:07:00'),
	(16, 1, 16, '4. Social Protection and OFW Assistance', 'Repatriation assistance', NULL, 'DMW', 'DFA; DSWD', NULL, 'Amber', NULL, NULL, NULL, NULL, NULL, 'From March 5 to 23, 2026, 2,052 OFWs and 578 dependents arrived in Manila.\nAs of March 24, 2026, 16,660 OFWs had received assistance and 586 OFs remained awaiting repatriation.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 16, '2026-04-24 15:07:00', '2026-04-24 15:07:00'),
	(17, 1, 17, '4. Social Protection and OFW Assistance', 'Easing school costs and other assistance for education', NULL, 'DepEd', 'DOLE and other concerned agencies', NULL, 'Amber', NULL, NULL, NULL, NULL, NULL, 'Bagong Pilipinas Serbisyo Fair activities in schools were conducted in pilot sites on March 13, 2026, in NCR on March 19, 2026, and nationwide on March 25, 2026.\nDepEd is also implementing no additional graduation fees and YAKAP in schools.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 17, '2026-04-24 15:07:00', '2026-04-24 15:07:00'),
	(18, 1, 18, '4. Social Protection and OFW Assistance', 'Assisting affected workers', NULL, 'SSS', '', NULL, 'Green', NULL, NULL, NULL, NULL, NULL, 'SSS is administering the Involuntary Separation Benefit for qualified members involuntarily separated from employment.\nBenefit amount ranges from PHP 5,000 to PHP 20,000 for up to two months.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 18, '2026-04-24 15:07:00', '2026-04-24 15:07:00'),
	(19, 1, 19, '4. Social Protection and OFW Assistance', 'Free calls and internet services for families of OFWs in the Middle East', NULL, 'DICT', 'DMW', NULL, 'Green', NULL, NULL, NULL, NULL, NULL, 'DICT regional offices, Digital Transformation Centers, and provincial offices are open to provide free calls and connectivity support for families communicating with OFWs in the Middle East.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 19, '2026-04-24 15:07:00', '2026-04-24 15:07:00'),
	(20, 1, 20, '5. Economic Stability, Service Continuity, and Implementation Support', 'Committee oversight, consolidated reporting, funding support, local coordination, and issue escalation', NULL, 'DEPDev Secretariat', 'DOE; DOF; DBM; concerned agencies', NULL, 'Amber', NULL, NULL, NULL, NULL, NULL, 'EO No. 110 dated March 24, 2026 declared a state of national energy emergency, adopted UPLIFT, constituted the UPLIFT Committee, and designated DEPDev as Secretariat.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 20, '2026-04-24 15:07:00', '2026-04-24 15:07:00');
